\cite{UDR94}
 A real valued function $u$ on $M$ is called convex if for every geodesic $\gamma:[a,b]\rightarrow M$, the following inequality holds
\begin{equation*}
u\circ\gamma((1-t)a+tb)\leq (1-t)u\circ\gamma(a)+tu\circ\gamma(b)\quad \forall t\in [0,1],
\end{equation*}
or if $u$ is differentiable, then 
\begin{equation*}
g(\nabla u,X)_x\leq u(exp_x\nabla u)-u(x), \ \forall X\in T_xM.
\end{equation*}

\label{th2}
Let $M$ be a complete Riemannian manifold and $u:M\rightarrow\mathbb{R}$ be a harmonic function. If there exists a point $p\in M$, where $M$ is rotationally symmetric and $u(p)<0$ with $inj(p)>1$, then 
\begin{equation*}
\int_{B_r}(K+u)dV=0\quad \forall r\in [0,inj(p)),
\end{equation*}
for some constant $K>0$.

Let $p\in M$ be a fixed point and $B_r$ be an open geodesic ball with center at $p$ and radius $r$ such that $0\leq r\leq inj(p)$ and also $inj(p)>1$. Now for each $r>0$, we define
\begin{equation}\label{eq1}
v(r)=\frac{1}{Vol(\partial B_r)}\int_{\partial B_r}udS_r,
\end{equation}
where $dS_r$ is the $(n-1)$-dimensional volume element of $B_r$. Since $M$ is rotationally symmetric at $p$ so using (\ref{eq12}) and (\ref{eq1}), we get
\begin{equation*}
v(r)=\frac{1}{Vol(\partial B_1)}\int_{\partial B_1}u(r\eta)dS_1.
\end{equation*}
Now differentiating the above function with respect to $r$, we obtain
$$v'(r)=\frac{1}{Vol(\partial B_1)}\int_{\partial B_1}\frac{\partial u}{\partial r}(r\eta)dS_1=\frac{1}{Vol(\partial B_r)}\int_{\partial B_1}\partial_rudS_r.$$
Hence for $r>0$, by using divergence theorem, we get
\begin{equation*}
v'(r)Vol(\partial B_r)=\int_{B_r}\Delta u dV.
\end{equation*}
In view of harmonicity of $u$, the above equation implies that $v'(r)=0$, i.e., $v=C$, a constant. Since $v$ is continuous so $v$ is constant in $[0,inj(p))$. Hence (\ref{eq1}) implies that 
\begin{equation}\label{eq2}
\int_{\partial B_r}udS_r=CVol(\partial B_r).
\end{equation}
Since $u(p)<0$, then there exists $\epsilon>0$, such that $u<0$ in $\partial B_\epsilon$. Hence
\begin{equation*}
C=\frac{1}{Vol(\partial B_\epsilon)}\int_{\partial B_\epsilon}udS_\epsilon<0.
\end{equation*}
Suppose $C=-K$, where $K>0$. Hence 
$$Vol(\partial B_r)=-\frac{1}{K}\int_{\partial B_r}udS_r.$$
Now from (\ref{eq2}), we get
\begin{equation}\label{eq5}
Vol(B_r)=\int_{0}^{r}Vol(\partial B_t)dt=-\frac{1}{K}\int_{0}^{r}\int_{\partial B_t}udS_tdt=-\frac{1}{K}\int_{B_r}udV.
\end{equation}
The above equation implies that
$$\int_{B_r}dV+\frac{1}{K}\int_{B_r}udV=0,$$
i.e.,
\begin{equation*}
\int_{B_r}(K+u)dV=0,\quad \forall r\in [0,inj(p)).
\end{equation*}

Suppose $(M,o)$ is a Riemannian manifold with a pole $o$ and is rotationally symmetric at $o$. If $u:M\rightarrow\mathbb{R}$ is a harmonic function such that $f(o)<0$, then there exists a constant $K>0$ such that
\begin{equation}\label{eq3}
\int_{B_r(o)}(K+u)dV=0,\quad \forall r\in [0,\infty).
\end{equation}

Assuming the conditions of the above corollary with $Ric_M\geq 0$, there exists a constant $C$ such that
\begin{equation}
\int_{B_r(o)}(C+u)dV=0,\quad \forall r\in [0,\infty).
\end{equation}

Let $u\in C^2(M)$ be a harmonic function. Since a manifold with positive semi-definite Ricci curvature does not admit any non-constant positive harmonic function \cite[p. 21]{SY94}, so there exists a point $q\in M$ such that $u(q)\leq 0$. Without loss of generality we can take $u(q)<0$, otherwise we have to subtract some positive constant. If $u(o)<0$, then taking $p=o$ the proof is complete. If $u(o)\geq 0$, then take $f(x)=u(x)-u(o)$ for $x\in M$. Hence $f$ is harmonic and $f(o)<0$. So using above corollary we get there is a constant $K$ such that for all $r>0$ 
\begin{eqnarray*}
0&=& \int_{B_r(o)}(K+f)dV,\\
&=&\int_{B_r(o)}(K+u(x)-u(o))dV.
\end{eqnarray*}
Hence taking $C=K+u(o)$, we get our result.

Let $(M,o)$ be a Riemannian manifold with $Ric_M\geq 0$. Suppose $M$ is rotationally symmetric at $o$. Then all non-constant convex functions $u\in C^2(M)$ with $|\nabla u|\in L^1(M)$ satisfy \begin{equation*}
\int_{B_r}(K+u)dV=0,\quad \forall r\in [0,\infty),
\end{equation*}
for some constant $K$.

\cite{CM97}
A complete Riemannian manifold $M$ is said to satisfy a uniform Neumann-Poincar\'{e} inequality if there exists $C_N<\infty$ such that, for all $p\in M$, $r>0$ and $u\in W^{1,2}_{loc}(M),$
\begin{equation*}
\int_{B_r}\Big(u-\frac{1}{Vol(B_r)}\int_{B_r}udV \Big)^2dV\leq C_Nr^2\int_{B_r}|\nabla u|^2dV.
\end{equation*}

Let $M$ be a $n$-dimensional complete Riemannian manifold with $Ric_M>-K$, for $K>0$ and $u\in W^{1,2}_{loc}(M)$ be a harmonic function and also $M$ satisfies a uniform
Neumann-Poincar\'{e} inequality. If $u$ is bounded below and there is a point $p\in M$ where $M$ is rotationally symmetric and such that $u(p)<0$ with $inj(p)>1$, then there exist $C>0,C_N$ and $c>0$, depending only on $n$, such that, for $0\leq r<inj(p)$, the following inequality holds 
\begin{equation}
\int_{B_r}\Big(u+C \Big)^2dV\leq (n-1)KC_Nr^2\int_{B_r}(u+c)^2dV.
\end{equation}

\label{th1}
Let  $(M,g)$ be a complete non-compact Riemannian manifold with $Ric_M>-K$, where $K>0$. If there exists a harmonic function $u\in C^2(M)$ which is bounded below and satisfies
\begin{equation}\label{eq6}
\mathcal{L}_{\nabla u}g+Ric\geq cg,
\end{equation}
then for some geodesic $\gamma:[0,\infty)\rightarrow M$, the function $u$ takes the form
\begin{equation}\label{eq9}
u(\gamma(t))=\frac{1}{\sqrt{(n-1)K}}(ct+G), \quad \forall 0\leq t<\infty,
\end{equation}
for some constant $G$.

Since $M$ is not compact, so by Ambrose's compactness criteria \cite{AM57} there exists a geodesic $\gamma:[0,\infty)\rightarrow M$, parametrized by arc length, such that 
\begin{equation}\label{eq7}
\int_{0}^{\infty}Ric(\gamma',\gamma')dt<\infty.
\end{equation}
Then taking $X=\nabla u$, along $\gamma$ we have
$$\mathcal{L}_Xg(\gamma',\gamma')=2g(\nabla_{\gamma'}X,\gamma')=2\frac{d}{dt}[g(X,\gamma')].$$
Hence using above equation and (\ref{eq6}), we obtain
$$Ric(\gamma',\gamma')\geq cg(\gamma',\gamma')-2\frac{d}{dt}[g(X,\gamma')].$$
Now taking $\gamma(0)=q$ and integrating and using the Cauchy-Schwarz inequality, we get
\begin{eqnarray*}
\int_{0}^{T}Ric(\gamma',\gamma')dt &\geq & c\int_{0}^{T}g(\gamma',\gamma')dt-2\int_{0}^{T}\frac{d}{dt}[g(X,\gamma')]dt\\
&\geq & cT+2g(X_q,\gamma'(0))-2g(X_{\gamma(T)},\gamma'(T))\\
&\geq & cT+2g(X_q,\gamma'(0))-2\left\lVertX_{\gamma(T)}\right\rVert.
\end{eqnarray*}
Now from (\ref{eq7}), we get
\begin{equation*}
\lim\limits_{T\rightarrow\infty}(cT+2g(X_q,\gamma'(0))-2\left\lVertX_{\gamma(T)}\right\rVert)<\infty.
\end{equation*}
Hence 
\begin{equation}
\lim\limits_{T\rightarrow\infty}(cT-2\left\lVertX_{\gamma(T)}\right\rVert)<\infty.
\end{equation}
Since $Ric_M>-K$ and $u$ is harmonic with lower bound, then gradient estimate Theorem (\ref{eq8}) implies that
\begin{equation*}
\lim\limits_{T\rightarrow\infty}(cT-2\sqrt{(n-1)K}(u-\inf_Mu))<\infty.
\end{equation*}
Consequently
\begin{equation*}
\lim\limits_{T\rightarrow\infty}(cT-2u\sqrt{(n-1)K})<\infty.
\end{equation*}
Hence there exists a constant $G$ such that
\begin{equation}
u(\gamma(t))=\frac{1}{\sqrt{(n-1)K}}(ct+G), \quad \forall 0\leq t<\infty,
\end{equation}
